-- Base de datos SQLite
-- 1. CREACIÓN DE LAS TABLAS

CREATE TABLE IF NOT EXISTS programas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombreprograma TEXT,
    abreviatura TEXT,
    tipo TEXT
);

CREATE TABLE IF NOT EXISTS asignaturas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    idprograma INTEGER,
    semestre TEXT,
    código TEXT,
    abreviatura TEXT,
    área TEXT,
    nombreasignatura TEXT,
    creditos INTEGER,
    tipoasignatura TEXT,
    tipocredito TEXT,
    prerequisito TEXT,
    FOREIGN KEY(idprograma) REFERENCES programas(id)
);

CREATE TABLE IF NOT EXISTS microcurriculo (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    idasignatura INTEGER,
    area TEXT,
    objetivogeneral TEXT,
    competencias TEXT,
    FOREIGN KEY(idasignatura) REFERENCES asignaturas(id)
);

CREATE TABLE IF NOT EXISTS contenidos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    idmicrocurriculo INTEGER,
    unidad TEXT,
    contenido TEXT,
    FOREIGN KEY(idmicrocurriculo) REFERENCES microcurriculo(id)
);

CREATE TABLE IF NOT EXISTS terceros (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    departamento TEXT,
    nombre TEXT,
    cedula TEXT,
    tipo TEXT,
    salario REAL,
    rol TEXT,
    entidad_bancaria TEXT,
    cuenta_bancaria TEXT,
    telefono TEXT,
    correo TEXT,
    fecha_nacimiento TEXT,
    contrato TEXT
);

CREATE TABLE IF NOT EXISTS sedes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    departamento TEXT,
    ciudad TEXT,
    categoria TEXT,
    transporte REAL
);

CREATE TABLE IF NOT EXISTS vinculaciones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    idsede INTEGER,
    idtercero INTEGER,
    idprograma INTEGER,
    semestre TEXT,
    idasignatura INTEGER,
    total_horas INTEGER,
    dia_horas_semanales TEXT,
    fecha_inicio TEXT,
    fecha_fin TEXT,
    FOREIGN KEY(idsede) REFERENCES sedes(id),
    FOREIGN KEY(idtercero) REFERENCES terceros(id),
    FOREIGN KEY(idprograma) REFERENCES programas(id),
    FOREIGN KEY(idasignatura) REFERENCES asignaturas(id)
);

-- Migración segura: si la columna ya existe SQLite retorna un error que
-- SQLiteEngineBootstrap ignora; si no existe, la crea correctamente.
ALTER TABLE vinculaciones ADD COLUMN idtercero INTEGER REFERENCES terceros(id);

CREATE TABLE IF NOT EXISTS sesiones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    idvinculacion INTEGER,
    idtercero INTEGER,
    fechasesionInicial TEXT,
    fechasesionFinal TEXT,
    duracion REAL,
    horas REAL,
    viatica INTEGER,
    FOREIGN KEY(idvinculacion) REFERENCES vinculaciones(id),
    FOREIGN KEY(idtercero) REFERENCES terceros(id)
);

